using Intranet.Data;
namespace Intranet.Api.Tests;
public sealed class AnalisisRbSpanishSchemaTests {
 [Fact]public void MapsSpanishStorageToExistingApiContract(){var group=Guid.NewGuid();const string json="{\"source\":{\"np\":\"J1907\"},\"requotation\":{\"enabled\":true,\"percentage\":0.1}}";var db=new AnalisisRbHistorialRegistro{Num_Registro=17,Cod_Grupo_Historial=group,Num_Version=2,Num_Registro_Anterior=12,Tip_Accion="U",Cod_Fabrica="001",Cod_OrdPro="J1907",Num_Prendas_Programadas=438,Imp_Precio_Comercial=1.305m,Min_Costura=12.05m,Min_Considerados=3.608m,Imp_Precio_Servicio=.39m,Imp_Otros_Gastos=.03m,Des_Ruta_Imagen=@"\\hialpesa103\EstPro$\EPB3392.jpg",Txt_Datos_Analisis=json,Cod_Version_Reglas="v2",Cod_Usuario="OPERARIO",Fec_Registro_UTC=new(2026,10,28,17,0,0),Cod_Traza="trace"};var row=db.ToContract();Assert.Equal(17,row.Id);Assert.Equal(group,row.RootId);Assert.Equal(2,row.Revision);Assert.Equal(12L,row.PreviousId);Assert.Equal("U",row.Action);Assert.Equal("001",row.Factory);Assert.Equal("J1907",row.Np);Assert.Equal(438,row.ProgrammedQuantity);Assert.Equal(1.305m,row.CommercialPrice);Assert.Equal(12.05m,row.SewingTime);Assert.Equal(3.608m,row.UsedTime);Assert.Equal(.39m,row.ServicePrice);Assert.Equal(.03m,row.OtherExpenses);Assert.Equal(db.Des_Ruta_Imagen,row.ImagePath);Assert.Equal(json,row.SnapshotJson);Assert.Equal("v2",row.RuleVersion);Assert.Equal("OPERARIO",row.GestionUser);Assert.Equal(DateTimeKind.Utc,row.SavedAtUtc.Kind);Assert.Equal("trace",row.TraceId);var api=System.Text.Json.JsonSerializer.Serialize(row,new System.Text.Json.JsonSerializerOptions(System.Text.Json.JsonSerializerDefaults.Web));Assert.Contains("\"programmedQuantity\":438",api);Assert.DoesNotContain("Num_Prendas_Programadas",api);}
 [Fact]public void DapperMapsSpanishResultColumns(){var table=new System.Data.DataTable();table.Columns.Add("Num_Registro",typeof(long));table.Columns.Add("Cod_OrdPro",typeof(string));table.Columns.Add("Imp_Precio_Comercial",typeof(decimal));table.Columns.Add("Txt_Datos_Analisis",typeof(string));table.Columns.Add("Des_Ruta_Imagen",typeof(string));table.Rows.Add(17L,"J1907",1.305m,"stored snapshot",DBNull.Value);using var reader=table.CreateDataReader();reader.Read();var row=Dapper.SqlMapper.GetRowParser<AnalisisRbHistorialRegistro>(reader)(reader).ToContract();Assert.Equal(17,row.Id);Assert.Equal("J1907",row.Np);Assert.Equal(1.305m,row.CommercialPrice);Assert.Equal("stored snapshot",row.SnapshotJson);Assert.Null(row.ImagePath);}
}
